<?php if($invoice): ?><section class="panel"><header class="panel-head"><div><span class="eyebrow">Payment release governance</span><h2>Accounting approval and settlement</h2></div><?= badge($effectiveInvoice??'draft') ?></header><p>Payment release requires match evidence, resolved or approved exceptions, and human approval for material or exceptional invoices.</p><div class="inline-actions"><?php if(can('approvals.submit')&&$match&&!in_array($effectiveInvoice,['approved_for_payment','paid','void','pending'],true)): ?><form action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="request_payment_release"><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><button class="button secondary" type="submit">Request Payment Release</button></form><?php endif; ?><?php if(can('purchase_orders.approve')&&$match&&!in_array($effectiveInvoice,['approved_for_payment','paid','void'],true)): ?><form action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="release_payment"><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><button class="button primary" type="submit">Release for Payment</button></form><?php endif; ?><?php if(can('purchase_orders.approve')&&$effectiveInvoice==='approved_for_payment'): ?><form action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="mark_paid"><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><button class="button primary" type="submit">Mark Paid</button></form><?php endif; ?></div><?php if(can('purchase_orders.approve')&&$effectiveInvoice!=='paid'&&$effectiveInvoice!=='void'): ?><form class="compact-form" action="<?= h(app_url('fulfillment-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="void_invoice"><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><label class="span-2"><span>Void evidence</span><textarea name="hold_reason" required></textarea></label><div class="span-2"><button class="button ghost" type="submit">Void Invoice</button></div></form><?php endif; ?></section><?php endif; ?>
